effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float t = acTime * speed;
  vec2 p = uv * scale;
  float v = sin(p.x + t) + sin(p.y * 1.3 - t * 0.8) + sin((p.x + p.y) * 0.7 + t * 1.2)
          + sin(length(p - scale * 0.5) * 2.0 - t * 2.0);
  v = v * 0.125 + 0.5;
  vec3 pl = mix(colorA.rgb, colorB.rgb, clamp(v, 0.0, 1.0));
  vec3 col = mix(c, pl, amount * mixAmt);
  gl_FragColor = vec4(col * a, a);
}
